/* AURORA 極光 — platform compatibility UI (src/ui/compat.js): the "audio paused — tap to resume" pill shown
   after an iOS interruption / backgrounding, and the splash warning when the page cannot make sound
   (http://<LAN-IP> is not a secure context). Tokens from css/style.css. */

/* ── resume pill ── */
.resume-pill {
  position: fixed; left: 50%; top: calc(var(--topbar-h, 60px) + 12px + env(safe-area-inset-top, 0px)); z-index: 4200;
  display: flex; align-items: center; gap: 11px; max-width: calc(100vw - 32px); padding: 10px 18px 10px 14px;
  border: 0; border-radius: 999px; cursor: pointer; text-align: left; color: var(--text, #e8ecff);
  font: inherit; font-family: var(--font-ui, system-ui, sans-serif);
  background: linear-gradient(180deg, rgba(44, 36, 20, .96), rgba(24, 20, 14, .96));
  box-shadow: 0 0 0 1px rgba(255, 196, 107, .45), 0 14px 40px rgba(0, 0, 0, .55), 0 0 40px rgba(255, 196, 107, .18);
  -webkit-backdrop-filter: blur(14px); backdrop-filter: blur(14px);
  opacity: 0; transform: translate(-50%, -8px) scale(.97);
  transition: opacity .25s ease, transform .35s var(--ease-spring, ease);
}
.resume-pill.is-in { opacity: 1; transform: translate(-50%, 0); }
.resume-pill[hidden] { display: none; }
.resume-pill:hover { box-shadow: 0 0 0 1px rgba(255, 196, 107, .8), 0 14px 40px rgba(0, 0, 0, .55), 0 0 50px rgba(255, 196, 107, .3); }
.resume-pill:focus-visible { outline: 2px solid var(--a-amber, #ffc46b); outline-offset: 3px; }
.resume-pill__dot {
  flex: none; width: 10px; height: 10px; border-radius: 50%; background: var(--a-amber, #ffc46b);
  box-shadow: 0 0 10px var(--a-amber, #ffc46b); animation: resume-blink 1.2s ease-in-out infinite;
}
.resume-pill__txt { display: flex; flex-direction: column; gap: 2px; min-width: 0; line-height: 1.25; }
.resume-pill__txt b { font-size: 14px; font-weight: 650; letter-spacing: .02em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.resume-pill__txt small { font-size: 11px; color: var(--text-dim, #8e97b8); letter-spacing: .04em; }
@keyframes resume-blink { 50% { opacity: .35; } }
@media (prefers-reduced-motion: reduce) { .resume-pill__dot { animation: none; } }

/* while the context is suspended the engine sends no state: freeze the "live" animations instead of faking motion */
.audio-suspended .dc-btn.is-live .dc-btn__live,
.audio-suspended .np__ic i,
.audio-suspended .sv-cover__eq i { animation-play-state: paused; }
.audio-suspended .np, .audio-suspended .th__progFill { opacity: .55; transition: opacity .3s; }

/* ── splash: this page cannot make sound (insecure context) ── */
.splash__warn {
  display: flex; flex-direction: column; align-items: center; gap: 3px; max-width: min(520px, calc(100vw - 32px));
  margin: 22px auto 0; padding: 10px 16px; border-radius: 12px; font-size: 12.5px; line-height: 1.45; text-align: center;
  color: var(--text, #e8ecff); background: rgba(255, 196, 107, .1); box-shadow: inset 0 0 0 1px rgba(255, 196, 107, .4);
}
.splash__warn b { color: var(--a-amber, #ffc46b); font-weight: 650; }
.splash__warn span { color: var(--text-dim, #8e97b8); font-size: 11.5px; }
.splash__warn small { margin-top: 3px; color: var(--text-faint, #5a6284); font-size: 11px; }
.splash__midi[hidden] { display: none; }

/* ── splash: boot failed (e.g. malformed saved data) → reset saved data ── */
.splash__reset {
  display: block; margin: 16px auto 0; padding: 9px 18px; border: 0; border-radius: 999px; cursor: pointer;
  font: inherit; font-size: 12.5px; color: var(--text, #e8ecff);
  background: rgba(255, 107, 129, .14); box-shadow: inset 0 0 0 1px rgba(255, 107, 129, .5);
  transition: background .2s;
}
.splash__reset:hover { background: rgba(255, 107, 129, .26); }
.splash__reset:focus-visible { outline: 2px solid var(--a-red, #ff6b81); outline-offset: 3px; }

/* AURORA 極光 — controls & keyboard (src/ui/components.js, src/ui/keyboard.js)
   Class prefix: ac-   Tokens come from css/style.css; the zero-specificity block below only
   provides fallbacks so components also render standalone (any real :root token wins). */

:where(:root) {
  --bg-0: #07080d; --bg-1: #0c0f18; --bg-2: #121726;
  --panel: rgba(22, 28, 46, .72); --panel-hi: rgba(38, 48, 78, .6);
  --line: rgba(140, 160, 220, .14); --text: #e8ecff; --text-dim: #8e97b8; --text-faint: #7a83a6;
  --a-cyan: #5cf2ff; --a-teal: #3ef0b0; --a-violet: #a78bfa; --a-pink: #ff6bd6; --a-amber: #ffc46b; --a-red: #ff6b81;
  --grad-aurora: linear-gradient(120deg, #3ef0b0, #5cf2ff 30%, #a78bfa 65%, #ff6bd6);
  --radius: 14px; --radius-sm: 8px; --shadow: 0 10px 40px rgba(0, 0, 0, .45);
  --font-ui: "Inter", "Noto Sans TC", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
}

/* ───────────────────────── shared ───────────────────────── */
.ac-knob, .ac-slider, .ac-toggle, .ac-select, .ac-env, .ac-xy, .ac-kb {
  --k-accent: var(--a-cyan);
  --k-glow: color-mix(in oklab, var(--k-accent) 65%, transparent);
  font-family: var(--font-ui);
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  box-sizing: border-box;
}
.ac-lbl { display: flex; flex-direction: column; align-items: center; line-height: 1.12; min-width: 0; }
.ac-zh { font-size: 12px; font-weight: 500; color: var(--text); letter-spacing: .02em; white-space: nowrap; }
.ac-en {
  font-size: var(--fs-cap, 11px); font-weight: 600; color: var(--text-faint); letter-spacing: var(--ls-cap, .07em);
  text-transform: uppercase; white-space: nowrap; margin-top: 1px; line-height: 1.15;
}
.ac-sr-only {
  position: absolute !important; width: 1px; height: 1px; margin: -1px; padding: 0; border: 0;
  overflow: hidden; clip: rect(0 0 0 0); clip-path: inset(50%); white-space: nowrap;
}
.ac-bubble-base, .ac-knob__bubble, .ac-slider__bubble, .ac-env__bubble {
  position: absolute; pointer-events: none; z-index: 30; white-space: nowrap;
  font: 600 11px/1 var(--font-mono); font-variant-numeric: tabular-nums; color: var(--text);
  padding: 5px 8px 5px; border-radius: 7px;
  background: linear-gradient(180deg, rgba(30, 37, 60, .96), rgba(14, 18, 30, .96));
  border: 1px solid color-mix(in oklab, var(--k-accent) 45%, transparent);
  box-shadow: 0 6px 22px rgba(0, 0, 0, .55), 0 0 16px color-mix(in oklab, var(--k-accent) 22%, transparent);
  opacity: 0;
  transition: opacity .16s ease, transform .2s cubic-bezier(.2, .8, .2, 1.2);
}

/* ───────────────────────── knob ───────────────────────── */
.ac-knob {
  --k-size: 50px;
  --k-mod: var(--a-amber);
  --k-g0: color-mix(in oklab, var(--k-accent) 62%, #3b3fd8);
  --k-g1: var(--k-accent);
  --k-g2: color-mix(in oklab, var(--k-accent) 70%, #ffffff);
  --k-ptr: color-mix(in oklab, var(--k-accent) 55%, #ffffff);
  position: relative;
  display: inline-flex; flex-direction: column; align-items: center; gap: 4px;
  min-width: calc(var(--k-size) + 10px);
  vertical-align: top;
}
@supports (color: oklch(from red l c h)) {
  .ac-knob {
    --k-g0: oklch(from var(--k-accent) calc(l - .1) c calc(h - 38));
    --k-g2: oklch(from var(--k-accent) calc(l + .07) calc(c * .85) calc(h + 14));
  }
}
.ac-knob.is-aurora {
  --k-accent: var(--a-violet);
  --k-g0: var(--a-teal); --k-g1: var(--a-cyan); --k-g2: var(--a-pink);
  --k-ptr: #ffffff;
}
.ac-knob--sm { --k-size: 34px; gap: 3px; }
.ac-knob--md { --k-size: 50px; }
.ac-knob--lg { --k-size: 68px; gap: 5px; }
.ac-knob--xl { --k-size: 104px; gap: 7px; }

.ac-knob__dial {
  position: relative; width: var(--k-size); height: var(--k-size);
  border-radius: 50%; cursor: ns-resize; touch-action: none; outline: none;
  transition: box-shadow .25s ease;
}
.ac-knob__dial svg { position: relative; display: block; width: 100%; height: 100%; overflow: visible; transition: transform .25s cubic-bezier(.3, 1.4, .5, 1); }
.ac-knob__dial:hover svg { transform: scale(1.035); }
.ac-knob.is-dragging .ac-knob__dial { box-shadow: 0 0 calc(var(--k-size) * .35) color-mix(in oklab, var(--k-accent) 22%, transparent); }
.ac-knob.is-dragging .ac-knob__dial svg { transform: scale(1.05); }
.ac-knob.has-mod .ac-knob__mod { opacity: 1; filter: drop-shadow(0 0 2.5px var(--k-mod)); }
.ac-knob__dial:focus-visible {
  box-shadow: 0 0 0 2px var(--bg-0), 0 0 0 3.5px color-mix(in oklab, var(--k-accent) 80%, transparent);
}
.ac-knob__aura {
  position: absolute; inset: -22%; border-radius: 50%; pointer-events: none; opacity: 0;
  background: radial-gradient(closest-side, color-mix(in oklab, var(--k-accent) 38%, transparent), transparent 75%);
  display: none;
}
.ac-knob--lg .ac-knob__aura, .ac-knob--xl .ac-knob__aura { display: block; }
.ac-knob.is-aurora .ac-knob__aura {
  background:
    radial-gradient(closest-side at 30% 60%, color-mix(in oklab, var(--a-teal) 30%, transparent), transparent 80%),
    radial-gradient(closest-side at 70% 40%, color-mix(in oklab, var(--a-pink) 26%, transparent), transparent 80%),
    radial-gradient(closest-side, color-mix(in oklab, var(--a-violet) 30%, transparent), transparent 80%);
}

.ac-knob__well { fill: rgba(4, 6, 12, .55); stroke: rgba(255, 255, 255, .035); stroke-width: 1; }
.ac-knob__ticks circle { fill: rgba(160, 175, 230, .28); transition: fill .25s ease; }
.ac-knob.has-scale .ac-knob__ticks circle { fill: rgba(160, 175, 230, .2); }
.ac-knob.has-scale .ac-knob__ticks circle.is-major { fill: rgba(170, 185, 235, .38); }
.ac-knob__ticks circle.is-lit, .ac-knob.has-scale .ac-knob__ticks circle.is-lit { fill: var(--k-g2); transition-duration: .08s; }
.ac-knob__track {
  fill: none; stroke: rgba(140, 160, 220, .15); stroke-width: 6.5; stroke-linecap: round;
  transition: stroke .2s ease;
}
.ac-knob__origin { fill: rgba(200, 210, 245, .45); }
.ac-knob__arc { fill: none; stroke-width: 6.5; stroke-linecap: round; }
.ac-knob__halo {
  fill: none; stroke: var(--k-accent); stroke-width: 9; stroke-linecap: round; opacity: .55;
  transition: opacity .2s ease;
}
.ac-knob.is-aurora .ac-knob__halo { stroke: var(--a-violet); }
.ac-knob__s0 { stop-color: var(--k-g0); }
.ac-knob__s1 { stop-color: var(--k-g1); }
.ac-knob__s2 { stop-color: var(--k-g2); }
.ac-knob__mod {
  fill: none; stroke: var(--k-mod); stroke-width: 3; stroke-linecap: round; opacity: .9;
  filter: drop-shadow(0 0 1.5px var(--k-mod));
}
.ac-knob__shadow { fill: #000; opacity: .55; }
.ac-knob__c0 { stop-color: #3d4766; }
.ac-knob__c1 { stop-color: #1b2135; }
.ac-knob__c2 { stop-color: #0c0f1a; }
.ac-knob__rim { fill: none; stroke-width: 1.3; }
.ac-knob__gloss { fill: #fff; opacity: 0; transition: opacity .2s ease; }
.ac-knob__ptr line { stroke: var(--k-ptr); stroke-width: 3.6; stroke-linecap: round; }
.ac-knob__ptr { filter: drop-shadow(0 0 1.6px var(--k-accent)); }

.ac-knob__dial:hover .ac-knob__track { stroke: rgba(150, 170, 235, .24); }
.ac-knob__dial:hover .ac-knob__gloss { opacity: .045; }
.ac-knob__dial:hover .ac-knob__halo, .ac-knob.is-dragging .ac-knob__halo { opacity: .85; }
.ac-knob.is-dragging .ac-knob__gloss { opacity: .07; }

.ac-knob__label { max-width: calc(var(--k-size) + 34px); }
.ac-knob__label .ac-zh, .ac-knob__label .ac-en { overflow: hidden; text-overflow: ellipsis; max-width: 100%; }
.ac-knob--sm .ac-zh { font-size: 11px; }
.ac-knob--sm .ac-en { display: none; }
.ac-knob--lg .ac-zh { font-size: 12.5px; }
.ac-knob--xl .ac-zh { font-size: 14px; font-weight: 600; letter-spacing: .04em; }
.ac-knob--xl .ac-en { font-size: var(--fs-cap, 11px); letter-spacing: .1em; }
.ac-knob__value {
  font: 500 11px/1.1 var(--font-mono); font-variant-numeric: tabular-nums;
  color: var(--text-dim); white-space: nowrap; transition: color .2s ease, text-shadow .2s ease;
}
.ac-knob--xl .ac-knob__value { font-size: 12px; }
.ac-knob.is-dragging .ac-knob__value, .ac-knob.is-bubble .ac-knob__value {
  color: var(--k-g2); text-shadow: 0 0 8px var(--k-glow);
}
.ac-knob__bubble { left: 50%; top: -6px; transform: translate(-50%, -85%) scale(.9); }
.ac-knob.is-dragging .ac-knob__bubble, .ac-knob.is-bubble .ac-knob__bubble {
  opacity: 1; transform: translate(-50%, -100%) scale(1);
}

/* ───────────────────────── slider ───────────────────────── */
.ac-slider {
  --k-g2: color-mix(in oklab, var(--k-accent) 70%, #ffffff);
  --pos: 0; --from: 0; --to: 0;
  position: relative; display: flex; gap: 6px; min-width: 0;
}
.ac-slider.is-aurora { --k-accent: var(--a-violet); }
.ac-slider--h { flex-direction: column; width: 100%; min-width: 120px; }
.ac-slider--v { flex-direction: column; align-items: center; height: 150px; width: 52px; }
.ac-slider__head { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
.ac-slider--h .ac-slider__head .ac-lbl { flex-direction: row; align-items: baseline; gap: 6px; }
.ac-slider--v .ac-slider__head { flex-direction: column; align-items: center; gap: 2px; }
.ac-slider__value {
  font: 500 11px/1 var(--font-mono); font-variant-numeric: tabular-nums; color: var(--text-dim);
  white-space: nowrap; transition: color .2s ease;
}
.ac-slider.is-dragging .ac-slider__value { color: var(--k-g2); }
.ac-slider__track { position: relative; outline: none; cursor: pointer; touch-action: none; border-radius: 99px; }
.ac-slider--h .ac-slider__track { height: 22px; padding: 0 9px; }
.ac-slider--v .ac-slider__track { flex: 1; width: 22px; padding: 9px 0; }
.ac-slider__track:focus-visible {
  box-shadow: 0 0 0 2px var(--bg-0), 0 0 0 3.5px color-mix(in oklab, var(--k-accent) 80%, transparent);
}
.ac-slider__rail {
  position: relative; border-radius: 99px;
  background: linear-gradient(180deg, rgba(0, 0, 0, .45), rgba(255, 255, 255, .03));
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, .6), 0 0 0 1px rgba(140, 160, 220, .1);
}
.ac-slider--h .ac-slider__rail { top: 8px; height: 6px; }
