/* AURORA 極光 — magic sound tools: 魔法調音 moods (src/ui/demo/smart.js), 自動演化 auto-evolve (evolve.js),
   A/B 音色變形 morph (morph.js). Class prefix: mt-. Tokens from css/style.css (fallbacks below for standalone pages).
   Every panel is its own size container: wide sheet ≥ 560 px, compact column 320–420 px. */

:where(:root) {
  --bg-0: #07080d; --bg-1: #0c0f18; --bg-2: #121726;
  --panel: rgba(22, 28, 46, .72); --line: rgba(140, 160, 220, .14);
  --text: #e8ecff; --text-dim: #8e97b8; --text-faint: #7a83a6;
  --a-cyan: #5cf2ff; --a-teal: #3ef0b0; --a-violet: #a78bfa; --a-pink: #ff6bd6; --a-amber: #ffc46b; --a-red: #ff6b81;
  --grad-aurora: linear-gradient(120deg, #3ef0b0, #5cf2ff 30%, #a78bfa 65%, #ff6bd6);
  --font-ui: "Inter", "Noto Sans TC", system-ui, sans-serif; --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --ease-out: cubic-bezier(.2, .8, .2, 1); --ease-spring: cubic-bezier(.3, 1.35, .5, 1);
}

/* ═══════════════════════════════ shared ═══════════════════════════════ */
.mt {
  container-type: inline-size;
  position: relative; display: flex; flex-direction: column; gap: 12px; min-width: 0;
  padding: 14px 14px 16px; border-radius: 16px; color: var(--text); font-family: var(--font-ui);
  background:
    radial-gradient(120% 80% at 0% 0%, rgba(62, 240, 176, .06), transparent 60%),
    radial-gradient(100% 90% at 100% 0%, rgba(167, 139, 250, .08), transparent 60%),
    linear-gradient(180deg, rgba(30, 38, 62, .62), rgba(16, 20, 34, .7));
  border: 1px solid rgba(160, 180, 240, .12);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .05), 0 6px 24px rgba(0, 0, 0, .32);
  -webkit-backdrop-filter: blur(16px) saturate(1.3); backdrop-filter: blur(16px) saturate(1.3);
  -webkit-tap-highlight-color: transparent;
}
.mt *, .mt *::before, .mt *::after { box-sizing: border-box; }
.mt button { font: inherit; color: inherit; }
.mt button:focus-visible, .mt input:focus-visible, .mt [tabindex]:focus-visible {
  outline: 2px solid color-mix(in oklab, var(--a-cyan) 80%, transparent); outline-offset: 2px;
}

.mt-bi { display: inline-flex; align-items: baseline; gap: 6px; min-width: 0; line-height: 1.15; }
.mt-bi__main { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mt-bi__sub {
  font-size: 10px; font-weight: 600; letter-spacing: .12em; text-transform: uppercase; color: var(--text-faint);
  white-space: nowrap;
}
.mt-bi__sub:empty { display: none; }
.mt-ic, .mt-title__ic { display: inline-grid; place-items: center; flex: none; line-height: 0; }

.mt-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; min-height: 30px; }
.mt-title { display: flex; align-items: center; gap: 8px; min-width: 0; }
.mt-title__ic {
  width: 28px; height: 28px; border-radius: 9px; color: #06121a;
  background: var(--grad-aurora); box-shadow: 0 0 18px rgba(92, 242, 255, .28);
}
.mt-title__txt .mt-bi__main { font-size: 14.5px; font-weight: 650; letter-spacing: .02em; flex: none; overflow: visible; }
.mt-title__txt .mt-bi__sub { min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.mt-head__actions { display: flex; align-items: center; gap: 6px; flex: none; }

.mt-pill {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 32px; padding: 0 12px 0 10px;
  border: 0; border-radius: 10px; cursor: pointer; color: var(--text-dim); white-space: nowrap; font-size: 12.5px; font-weight: 500;
  background: linear-gradient(180deg, rgba(40, 48, 76, .55), rgba(20, 25, 40, .6));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .06), 0 0 0 1px rgba(140, 160, 220, .12);
  transition: color .18s ease, box-shadow .2s ease, transform .15s ease, opacity .2s ease;
}
.mt-pill:hover:not(:disabled) { color: var(--text); box-shadow: inset 0 1px 0 rgba(255, 255, 255, .08), 0 0 0 1px rgba(167, 139, 250, .45), 0 0 16px rgba(167, 139, 250, .14); }
.mt-pill:active:not(:disabled) { transform: scale(.96); }
.mt-pill:disabled { opacity: .38; cursor: default; }
.mt-pill.is-primary:not(:disabled) { color: #06121a; background: var(--grad-aurora); box-shadow: 0 0 18px rgba(92, 242, 255, .3); font-weight: 650; }
.mt-pill.is-primary:not(:disabled) .mt-bi__sub { color: rgba(6, 18, 26, .6); }

.mt-row { display: grid; grid-template-columns: auto auto minmax(80px, 1fr) auto; align-items: center; gap: 8px; }
.mt-row__lbl { min-width: 64px; }
.mt-row__lbl .mt-bi__main { font-size: 12px; color: var(--text-dim); }
.mt-row__end { font-size: 10.5px; color: var(--text-faint); white-space: nowrap; }
.mt .ac-slider--h { min-width: 0; }

.mt-chip {
  --mc: var(--a-cyan);
  display: inline-flex; align-items: center; gap: 7px; height: 30px; padding: 0 10px; border: 0; border-radius: 99px; cursor: pointer;
  color: var(--text-dim); font-size: 12px;
  background: rgba(20, 25, 40, .55); box-shadow: inset 0 0 0 1px rgba(140, 160, 220, .14);
  transition: color .18s ease, box-shadow .2s ease, background .2s ease, transform .15s ease;
}
.mt-chip__dot { width: 8px; height: 8px; border-radius: 50%; background: color-mix(in oklab, var(--mc) 40%, #2a3048); transition: background .2s ease, box-shadow .2s ease; }
.mt-chip__n { font: 600 10px/1 var(--font-mono); color: var(--text-faint); min-width: 12px; text-align: right; }
.mt-chip[aria-pressed="true"] { color: var(--text); background: color-mix(in oklab, var(--mc) 12%, rgba(20, 25, 40, .7)); box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--mc) 55%, transparent), 0 0 14px color-mix(in oklab, var(--mc) 18%, transparent); }
.mt-chip[aria-pressed="true"] .mt-chip__dot { background: var(--mc); box-shadow: 0 0 8px var(--mc); }
.mt-chip:active { transform: scale(.96); }

/* ═══════════════════════════════ 魔法調音 moods ═══════════════════════════════ */
